const inputs = yield* llm.inputs expect(inputs).toHaveLength(2)
const messages = yield* MessageV2.filterCompactedEffect(session.id) const summaryIndex = messages.findIndex((message) => message.info.role === "assistant" && message.info.summary) expect(summaryIndex).toBe(messages.length - 1) const summary = messages[summaryIndex] const text = summary?.parts .filter((part): part is MessageV2.TextPart => part.type === "text") .map((part) => part.text) .join("\n") expect(text).toContain("protected calibration flow") expect(text).not.toContain("Prefer tools and edits")
